// ⚠️ 生成物，勿手改。真源 = packages/demo/src/demo.css
// 由 scripts/gen-css.mjs 生成（`pnpm run gen:css`）：改样式请改那个 .css 文件后重新生成。
export const DEMO_CSS = "/* demo 预览站的文档骨架样式（Bootstrap 文档站式：提示框 + 左示例右代码 + 用法 + API 表）。\n   真源在这里，由 scripts/gen-css.mjs 生成 demo-css.generated.ts，运行时经 createStyleKit 注入。\n   只消费 var(--dshpc-*)：明暗交给 token，本文件不写死任何颜色。 */\n\n/* 备注框本体是核心 StripCard（方角 + 左 4px 通高色条 + 同色系浅底），这里只补行内排版。 */\n.dshpc-doc-note {\n  margin-bottom: 16px;\n}\n\n.dshpc-doc-note__body {\n  display: flex;\n  gap: 8px;\n  font-size: var(--dshpc-font-md);\n  line-height: var(--dshpc-line-md);\n}\n\n.dshpc-doc-note__mark {\n  flex: none;\n  font-weight: 600;\n  color: var(--dshpc-business);\n}\n\n/* 一个 Note 框内承载多段说明：mark 是左侧标签，content 是右侧竖排段落列。 */\n.dshpc-doc-note__content {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n.dshpc-doc-note__p {\n  line-height: var(--dshpc-line-md);\n}\n\n/* 边框盒：用法块 / API 表的共同外壳 */\n.dshpc-doc-block {\n  border: 1px solid var(--dshpc-border-faint);\n  border-radius: var(--dshpc-radius-md);\n  background: var(--dshpc-surface-1);\n  padding: 12px 14px;\n  margin: 0 0 16px;\n}\n\n.dshpc-doc-label {\n  font-size: var(--dshpc-font-xs);\n  font-weight: 600;\n  letter-spacing: 0.06em;\n  text-transform: uppercase;\n  color: var(--dshpc-fg-4);\n  margin-bottom: 8px;\n}\n\n.dshpc-doc-example {\n  border: 1px solid var(--dshpc-border-faint);\n  border-radius: var(--dshpc-radius-md);\n  background: var(--dshpc-surface-1);\n  overflow: hidden;\n  margin: 0 0 16px;\n}\n\n.dshpc-doc-example__head {\n  padding: 10px 14px;\n  border-bottom: 1px solid var(--dshpc-border-faint);\n}\n\n.dshpc-doc-example__title {\n  font-size: var(--dshpc-font-lg);\n  font-weight: 600;\n  color: var(--dshpc-fg);\n}\n\n.dshpc-doc-example__hint {\n  margin-top: 2px;\n  font-size: var(--dshpc-font-sm);\n  line-height: var(--dshpc-line-sm);\n  color: var(--dshpc-fg-3);\n}\n\n/* 两栏；容器窄到放不下两列 300px 时自动塌成一列（代码落到示例下方）。\n   行高 = 两栏里较高的那一栏（grid 默认 stretch）⇒ 矮的一栏被拉齐，不再出现「左边很高、右边一条小滚动条」。 */\n.dshpc-doc-example__body {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));\n  align-items: stretch;\n}\n\n.dshpc-doc-example__demo {\n  min-width: 0;\n  min-height: 0;\n  padding: 14px;\n  display: flex;\n  flex-direction: column;\n}\n\n.dshpc-doc-example__code {\n  min-width: 0;\n  min-height: 0;\n  padding: 14px;\n  border-left: 1px solid var(--dshpc-border-faint);\n  background: var(--dshpc-code-surface);\n  display: flex;\n  flex-direction: column;\n}\n\n/* 代码区吃掉整栏剩余高：表头「代码」两个字不被滚走，代码本身按行高自适应\n   （不写死 max-height —— 那会在示例很高时代码栏里挤出一条小滚动条）。 */\n.dshpc-doc-example__scroll {\n  flex: 1 1 auto;\n  min-height: 0;\n  overflow: auto;\n}\n\n.dshpc-doc-api {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: var(--dshpc-font-md);\n}\n\n.dshpc-doc-api th,\n.dshpc-doc-api td {\n  text-align: left;\n  padding: 6px 10px;\n  border-bottom: 1px solid var(--dshpc-border-faint);\n  vertical-align: top;\n}\n\n.dshpc-doc-api th {\n  font-weight: 600;\n  color: var(--dshpc-fg-3);\n  white-space: nowrap;\n}\n\n.dshpc-doc-api td:first-child {\n  font-family: var(--dshpc-font-mono);\n  white-space: nowrap;\n  color: var(--dshpc-fg);\n}\n\n/* 最后一行不留底边框：表格底部不再多出一条悬空横线 */\n.dshpc-doc-api tbody tr:last-child td {\n  border-bottom: none;\n}\n"
